class PeriodicTask:
    def __init__(self, C_i, T_i):
        self.C = C_i
        self.T = T_i

    def generate_jobs(self, current_time):
        # Simplified: generates one job for a given release time
        release_time = current_time
        deadline = current_time + self.T
        return {'release': release_time, 'execution_needed': self.C, 'deadline': deadline}

def calculate_system_utilization(task_set):
    U_T = 0.0
    for task_i in task_set:
        U_T += calculate_task_utilization(task_i)
    return U_T

